/**
 * ============================================================================
 * GLOBAL HISTORY MANAGER
 * Manages history with a global FIFO queue (legacy mode)
 * ============================================================================
 */
export class GlobalHistoryManager {
    constructor(maxSize?: number);
    history: any[];
    maxSize: number;
    /**
     * Add event to global history
     */
    add(eventData: any): void;
    /**
     * Get history for a specific rule
     */
    get(ruleId: any): any[];
    /**
     * Get all history
     */
    getAll(): any[];
    /**
     * Get history statistics
     */
    getStats(): {
        mode: string;
        totalRules: number;
        totalEvents: number;
        maxSize: number;
        perRule: any;
    };
    /**
     * Get total event count
     */
    size(): number;
    /**
     * Clear history for specific rule
     */
    clearRule(ruleId: any): void;
    /**
     * Clear all history
     */
    clear(): void;
    /**
     * Check if history exists for a rule
     */
    has(ruleId: any): boolean;
}
